  ('3eb5dbf0-d31a-5e53-8d9b-d57cead10cf8', 'IN-26-9009', 'IN', 'd9c0c755-fce1-54cc-a17a-ff1f950f666b', 'complete', null, '2026-10-29', 'Install — per order', 'order', true, null, null, 'Tinas en unidades 24, 25 estan al revés se tienen que cambiar. Shower en lote 28 no listo faltan valvulas.', 'Tubs in units 24, 25 are backwards (wrong hand) and have to be changed. Shower in lot 28 not ready -- missing valves.', false, '{"paper": "install p11"}'::jsonb),
