  ('0b76a9a0-710e-54e7-b8ec-64d8d031da16', 'ST-26-9013', 'ST', 'cc554b8e-fb75-5df3-b5f2-2cc3b2742b3d', 'canceled', 'This job was canceled. They did not receive the delivery, supposedly because they hadn''t ordered the tubs yet, and this job is not ready. Prevailing wage.', '2026-10-30', 'Stock — BLDG # A', 'order', true, '07:00', '09:00', '(diagonal across grid) SE CANCELO ESTE TRABAJO. NOTES: EN ESTE TRABAJO NO RECIBIERO EL DELIVERY QUE PORQUE NO AVIAN PEDIDO LAS TINAS AUN Y NO ESTA LISTO ESTE TRABAJO. (bottom) PREW WAGE', 'This job was canceled. They did not receive the delivery, supposedly because they hadn''t ordered the tubs yet, and this job is not ready. Prevailing wage.', false, '{"paper": "stocking p2"}'::jsonb),
  ('05703562-6626-5bd4-9ba8-c9b5cef284f4', 'ST-26-9014', 'ST', 'f1bb50bc-abf8-5a89-b88a-aa742f95e28e', 'complete', null, '2026-10-30', 'Stock — LEVEL 3,4,5', 'order', true, '10:00', '15:30', 'TODO QUEDO BIEN DENTRO DE LOS BANOS.', 'Everything was left fine inside the bathrooms.', true, '{"paper": "stocking p3"}'::jsonb),
  ('79cf7f94-b315-5fc5-b3ae-5c8d2bad6c04', 'ST-26-9015', 'ST', 'cc554b8e-fb75-5df3-b5f2-2cc3b2742b3d', 'canceled', 'They still don''t want the tubs. The job isn''t ready. All the tubs were returned.', '2026-10-30', 'Stock — per order', 'order', true, '07:00', '09:00', 'Aun no quieren las tinas. El trabajo no esta listo. Todas las tinas se regresaron.', 'They still don''t want the tubs. The job isn''t ready. All the tubs were returned.', false, '{"paper": "stocking p4"}'::jsonb),
  ('8b591363-1fd3-5013-b161-813d6709cbc3', 'ST-26-9016', 'ST', 'f1bb50bc-abf8-5a89-b88a-aa742f95e28e', 'complete', null, '2026-10-30', 'Stock — per order', 'order', true, '10:00', '15:30', 'todo se estaqueo y se metio al baño', 'Everything was stocked and put into the bathroom.', false, '{"paper": "stocking p5"}'::jsonb),
  ('d3206a6f-7ab2-5771-92d5-309b58ec9853', 'ST-26-9017', 'ST', '8c440078-bf90-5023-ac2d-869edd181253', 'complete', null, '2026-10-30', 'Stock — Phase-3', 'order', true, '07:00', '10:50', '(grid) TODO SE ESTAQUEO SIN DAÑOS. NOTES: TAMBIEN SE METIERON A LOS BAÑOS UNIDADES QUE ESTABAN PENDIENTES', 'Everything was stocked without damage. Also moved into the bathrooms units that were pending (previously stockpiled).', false, '{"paper": "stocking p6"}'::jsonb),
