insert into public.notes (id, work_order_id, body, body_language, body_translated) values
  ('c69ced14-ce56-588f-a3a2-24ce732eb18f', '15a369c5-670c-56cf-98f6-e6d7c521a71c', 'Crew note (from paper): Unidades 412 la ART6036L y 146 la ART6036R nesesitan reparacion ASAP te mande fotos se instalaron', 'es', 'Units 412 (the ART6036L) and 146 (the ART6036R) need repair ASAP; I sent you photos; they were installed.'),
  ('66c660aa-669a-5117-8637-c3c6de575ac9', 'a3fb9bbf-c00e-593f-8923-2c09112a2638', 'Crew note (from paper): Se termino lo que estaba listo.', 'es', 'We finished what was ready.'),
  ('068a9dda-05f0-53cf-a0e0-a1e01682c6bf', '8076684c-41c9-5f1f-b055-45864b7d0235', 'Crew note (from paper): (arrows/headers drawn over columns: ''Foor 3'', ''Foor 4'', ''Foor 5'')', 'es', 'Floor 3 / Floor 4 / Floor 5 column groupings'),
  ('bea9b216-355c-54a1-b21f-27759d898bf4', '14f37454-b373-5ba9-8efa-44a6a0698158', 'Crew note (from paper): No se instalo nada porque no an puesto el inpremiable Edgar diso que regresayamos el martes de la semana procsima', 'es', 'Nothing was installed because they haven''t put up the waterproofing (impermeable). Edgar said to come back Tuesday of next week.'),
  ('f73bd0aa-2e40-5de6-b52c-466d79e57de6', 'eec60944-cd6d-5505-a68f-dfb1a4cd5f9f', 'Crew note (from paper): Se completo todo lo que estava listo', 'es', 'Everything that was ready was completed.'),
  ('c1246ca0-5c69-5f4a-9e56-a14215cab26b', '5a34b42c-81ac-5710-90eb-bec6224bf0cc', 'Crew note (from paper): (on line 310) Pull out Resset', 'es', 'Lot 310: pulled out and reset (rework of an existing tub)'),
  ('557d6dd2-933e-5bea-9b47-406f1ff59c6d', '3eb5dbf0-d31a-5e53-8d9b-d57cead10cf8', 'Crew note (from paper): Tinas en unidades 24, 25 estan al revés se tienen que cambiar. Shower en lote 28 no listo faltan valvulas.', 'es', 'Tubs in units 24, 25 are backwards (wrong hand) and have to be changed. Shower in lot 28 not ready -- missing valves.'),
  ('c493d1e4-50e8-5bbd-9b45-22c9ec83e1ef', '4e78dd48-f1ef-5ee5-9226-b777ce25cd10', 'Crew note (from paper): Lot #69 60x32 RH ocupa reparacion. No Super!!! No Firma!!!  (each SKU has small ''et ro'' annotation above it)', 'es', 'Lot #69 60x32 RH needs repair. No superintendent!!! No signature!!!'),
  ('a6eabfc1-0697-5f7f-a337-80606105c76c', '0e85b838-ca38-5077-920a-5c571a241c84', 'Crew note (from paper): No habia Supervisor por eso no firma', 'es', 'There was no supervisor, so no signature.'),
  ('fb3655bd-c911-5282-a57a-7f12743b7429', '0b76a9a0-710e-54e7-b8ec-64d8d031da16', 'Crew note (from paper): (diagonal across grid) SE CANCELO ESTE TRABAJO. NOTES: EN ESTE TRABAJO NO RECIBIERO EL DELIVERY QUE PORQUE NO AVIAN PEDIDO LAS TINAS AUN Y NO ESTA LISTO ESTE TRABAJO. (bottom) PREW WAGE', 'es', 'This job was canceled. They did not receive the delivery, supposedly because they hadn''t ordered the tubs yet, and this job is not ready. Prevailing wage.'),
  ('f676f99a-c8e5-5e0d-8395-c373e7e430f3', '05703562-6626-5bd4-9ba8-c9b5cef284f4', 'Crew note (from paper): TODO QUEDO BIEN DENTRO DE LOS BANOS.', 'es', 'Everything was left fine inside the bathrooms.'),
  ('a7e57bda-3b6f-58e7-a522-f3542e0d9e3d', '79cf7f94-b315-5fc5-b3ae-5c8d2bad6c04', 'Crew note (from paper): Aun no quieren las tinas. El trabajo no esta listo. Todas las tinas se regresaron.', 'es', 'They still don''t want the tubs. The job isn''t ready. All the tubs were returned.'),
  ('f289a0a8-0dcc-5b7a-86ed-e898380e9f81', '8b591363-1fd3-5013-b161-813d6709cbc3', 'Crew note (from paper): todo se estaqueo y se metio al baño', 'es', 'Everything was stocked and put into the bathroom.'),
  ('f903bde4-8bf3-5272-beab-654a2a552154', 'd3206a6f-7ab2-5771-92d5-309b58ec9853', 'Crew note (from paper): (grid) TODO SE ESTAQUEO SIN DAÑOS. NOTES: TAMBIEN SE METIERON A LOS BAÑOS UNIDADES QUE ESTABAN PENDIENTES', 'es', 'Everything was stocked without damage. Also moved into the bathrooms units that were pending (previously stockpiled).'),
  ('ad4a5fb6-6011-500b-ac36-8fdfed5d96c2', '6c6bfb8a-6dce-54ac-9e71-e68d0e06ab1b', 'Crew note (from paper): SE ESTAQUEARON LAS UNIDADES QUE ESTABAN LISTAS. PH1 - LEVELS- 3,4. COMO EN UNA SEMANA HABRA MAS UNIDADES PARA ESTAQUEAR. (margin) RESTOCK', 'es', 'Stocked the units that were ready (PH1 levels 3,4). In about a week there will be more units to stock.')
